class Tracker:
    def __init__(self):
        self._c = {}  # lower-cased name -> combatant
        self._turn = []  # names in this round's turn order
        self._idx = 0  # position of the current combatant in _turn
        self.round = 0  # 0 until start() has been called

    @staticmethod
    def _key(name):
