    def order(self):
        def key(c):
            return (-c["roll"], -c["dex"], TIE_TEAM.index(c["team"]), c["name"].lower())

        return [c["name"] for c in sorted(self._c.values(), key=key)]

    def current(self):
        return self._turn[self._idx] if self.round else None

    def start(self):
        if not self._c:
            raise ValueError("nobody is in the fight")
