        for label in list(conds):
            conds[label] -= 1
            if conds[label] <= 0:
                del conds[label]

    def _begin(self, name):
        if TICK_AT == "start":
            self._tick(name)

    def _end(self, name):
        if TICK_AT == "end":
            self._tick(name)

